{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Bumetanide, a structurally related loop diuretic with a sulfamoylbenzoic acid and carboxylic acid, showed 80% absolute oral bioavailability in normal subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Metoclopramide in patients with cirrhosis had an absolute oral bioavailability of 79.0 ± 18.8%, indicating that cirrhosis does not inherently reduce oral bioavailability and supporting a high prediction under the stated condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tolfenamic acid in patients with alcoholic cirrhosis showed about 100% oral bioavailability, further supporting that high oral bioavailability can be maintained in cirrhosis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Azosemide, a close structural analogue sharing the sulfamoyl-chloro-aminomethyl core, had an absolute oral bioavailability of approximately 20.4% in healthy fasting humans, providing a contradictory low anchor, though it remains near the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is furosemide, a sulfamoylbenzoic acid loop diuretic. Most high-transfer experimental evidence, including the closely related bumetanide and cirrhosis-specific metoclopramide and tolfenamic acid data, supports oral bioavailability well above 20%. The closest low-availability analogue, azosemide, is only borderline at ~20.4% and is outweighed by the broader high-bioavailability pattern.",
  "evidence_gaps": [
    "No direct furosemide bioavailability measurement in cirrhosis is provided; the prediction relies on structurally and condition-related analogues.",
    "Furosemide-specific absorption variability and the impact of cirrhosis on its first-pass metabolism are not directly captured by the supplied records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

